"""Version-against-version camera denoise on the out-of-protocol RAW files (no Lightroom reference).
Masks from the IPR neutral render of the first executable (state 0/0, identical for every version,
checked). Usage: python wide_versions.py OUT.json EXE:LABEL [EXE:LABEL ...]"""
import json, sys, time
from pathlib import Path
import numpy as np
sys.path.insert(0, str(Path(__file__).parent))
from strength_law import RenderServer, masks, metrics, ROOT  # noqa: E402
from signed_probe import dots  # noqa: E402

BASE = ROOT / "tests/image/base-hors-protocole"
STATES = ("0/0/0", "70/25/0", "100/0/0", "0/100/0", "100/100/0")


def main():
    out = Path(sys.argv[1])
    specs = [s.rsplit(":", 1) for s in sys.argv[2:]]
    report = json.loads(out.read_text()) if out.exists() else {}
    raws = sorted(p for p in BASE.iterdir() if p.suffix.upper() in (".CR3", ".CR2"))
    servers = {}
    try:
        for exe, label in specs:
            servers[label] = RenderServer(Path(exe), timeout=900).__enter__()
        for raw in raws:
            if raw.stem in report:
                continue
            t0 = time.time()
            entry = {"file": raw.name}
            m = None
            for exe, label in specs:
                entry[label] = {}
                for key in STATES:
                    lum, col, _ = map(int, key.split("/"))
                    im = servers[label].render(raw, "neutral", 0, camera_denoise={"luminance": lum, "chrominance": col})[0].astype(np.float32) / 257.0
                    if m is None:
                        m = masks(im)
                        entry["mask_pixels"] = {k: int(v.sum()) for k, v in m.items()}
                    entry[label][key] = {"metrics": metrics(im, m),
                                         "dots": {z: dots(im, m[z]) for z in ("dark", "mid_flat") if m[z].sum() > 2000}}
            report[raw.stem] = entry
            out.write_text(json.dumps(report, indent=1))
            print(raw.stem, f"{time.time() - t0:.0f}s", flush=True)
    finally:
        for server in servers.values():
            server.__exit__(None, None, None)


if __name__ == "__main__":
    main()
